function updateExtensionStore(){if(!$('store-list')){const dialog=$('store-confirm');if(dialog){dialog.close();dialog.remove();}return;}const signature=JSON.stringify([state.catalog,state.catalogLoading,state.extensions,state.pendingInstall,state.storeBusy,state.status,$('store-search').value]);if(signature===storeSignature)return;storeSignature=signature;const root=$('store-list');root.replaceChildren();$('store-status').textContent=trMessage(state.status)||(state.catalogLoading?tr('Проверяем актуальные версии…'):state.catalog?.length?tr('Каталог загружен. Версия пакетов Chrome Web Store проверяется при установке.'):tr('Не удалось получить каталог. Проверьте подключение и повторите обновление.'));const query=$('store-search').value.trim().toLocaleLowerCase();for(const p of state.catalog||[]){if(!`${p.name} ${p.description}`.toLocaleLowerCase().includes(query))continue;const card=el('section','store-package');const title=el('div','store-package-title');title.append(icon('extension'),el('h3','',p.name));card.append(title,el('p','description',tr(p.description)));const version=el('p','store-version',p.version?(p.version.startsWith('Актуальная')?tr(p.version):tr`Версия ${p.version}`):trMessage(p.error)||tr('Версия недоступна'));card.append(version);const controls=el('div','control-row');const installed=state.extensions.some(x=>x.name.toLocaleLowerCase()===p.name.toLocaleLowerCase());const install=button(installed?tr('Установлено'):tr('Установить'),()=>post('store_prepare',{id:p.id}));install.disabled=installed||!p.download||state.storeBusy||!!state.pendingInstall;controls.append(install,button(tr('Разработчик'),()=>post('store_source',{id:p.id})));card.append(controls);root.append(card);}if(!root.children.length&&!state.catalogLoading)root.append(el('p','empty',tr('Расширения не найдены.')));let dialog=$('store-confirm');if(!state.pendingInstall){if(dialog){dialog.close();dialog.remove();}return;}const p=state.pendingInstall;if(!dialog){dialog=el('dialog','confirm-dialog store-confirm');dialog.id='store-confirm';dialog.setAttribute('aria-labelledby','install-title');const heading=el('h2','',tr`Установить ${p.name}?`);heading.id='install-title';dialog.append(heading,el('p','description',tr`Версия ${p.version}. Расширение запрашивает следующие разрешения:`));const permissions=el('ul','permission-list');for(const permission of p.permissions)permissions.append(el('li','',trMessage(permission)));if(!p.permissions.length)permissions.append(el('li','',tr('Дополнительные разрешения не указаны.')));dialog.append(permissions);const controls=el('div','control-row');controls.append(button(tr('Отмена'),()=>post('store_cancel')),button(tr('Установить'),()=>post('store_confirm')));dialog.append(controls);dialog.addEventListener('cancel',e=>{e.preventDefault();if(!state.storeBusy)post('store_cancel');});document.body.append(dialog);dialog.showModal();controls.firstChild.focus();}for(const b of dialog.querySelectorAll('button'))b.disabled=state.storeBusy;}
function library(root,kind){const content=el('article','library-content');content.append(button(tr('К браузеру'),()=>post('view',{value:''}),'back-browser','back'));const top=el('div','page-top');top.append(el('h2','',kind==='history'?tr('Журнал'):tr('Закладки')),button(tr('Очистить список'),()=>confirmClearLibrary(kind)));content.append(top);const list=el('div');list.id='library-list';content.append(list);root.append(content);}
function confirmClearLibrary(kind){const dialog=el('dialog','confirm-dialog');const heading=el('h2','',kind==='bookmarks'?tr('Удалить все закладки?'):tr('Очистить журнал?'));heading.id='confirm-title';dialog.setAttribute('aria-labelledby',heading.id);dialog.append(heading,el('p','description',kind==='bookmarks'?tr('Все закладки будут удалены. Отменить это действие нельзя.'):tr('Список посещённых страниц будет очищен. Отменить это действие нельзя.')));const actions=el('div','control-row');actions.append(button(tr('Отмена'),()=>dialog.close()),button(tr('Очистить список'),()=>{post('clear_library',{value:kind,confirmed:true});dialog.close();},'soft-button danger-button'));dialog.append(actions);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});document.body.append(dialog);dialog.showModal();actions.firstChild.focus();}
function entries(root,items,emptyText,build){root.replaceChildren();if(!items.length){root.append(el('p','empty',emptyText));return;}const list=el('div','entry-list');items.forEach(item=>list.append(build(item)));root.append(list);}
function entry(title,subtitle){const row=el('div','entry'),main=el('div','entry-main');main.append(el('div','entry-title',title),el('div','entry-sub',subtitle));row.append(main);return row;}
function updateLists(){const signature=JSON.stringify([state.view,state.credentials,state.extensions,state.bookmarks,state.history]);if(signature===listSignature)return;listSignature=signature;if($('vault-list'))entries($('vault-list'),state.credentials,tr('Сохранённых паролей пока нет'),c=>{const row=entry(c.origin,c.username);row.append(button(tr('Копировать пароль'),()=>post('copy_password',{origin:c.origin,username:c.username}),'icon-button','copy'),button(tr('Удалить запись'),()=>post('delete_password',{origin:c.origin,username:c.username}),'icon-button','trash'));return row;});if($('extensions-list'))entries($('extensions-list'),state.extensions.filter(x=>x.id!=='cfhdojbkjhnklbpkdaibdccddilifddb'),tr('Установленных расширений нет'),x=>{const row=el('div','entry extension-entry');const open=button(x.name,()=>post('extension_open',{id:x.id}),'extension-open-name');open.textContent='';open.disabled=!x.enabled;open.append(extensionIcon(x),el('span','',x.name));const toggle=el('label','extension-toggle');const input=el('input');input.type='checkbox';input.setAttribute('role','switch');input.setAttribute('aria-label',tr`Включить ${x.name}`);input.checked=x.enabled;input.addEventListener('change',()=>{input.disabled=true;post('extension_toggle',{id:x.id});});toggle.append(input);row.append(open,toggle,button(tr`Удалить ${x.name}`,()=>confirmExtensionRemove(x),'icon-button','trash'));return row;});if($('library-list'))entries($('library-list'),state[state.view]||[],tr('Список пока пуст'),x=>{const row=entry(x.Title,x.Url);const open=button(tr('Открыть страницу'),()=>post('navigate',{value:x.Url}),'icon-button','forward');row.append(open);if(state.view==='bookmarks')row.append(button(tr`Удалить закладку: ${x.Title}`,()=>post('delete_bookmark',{url:x.Url}),'icon-button','trash'));row.addEventListener('dblclick',()=>post('navigate',{value:x.Url}));return row;});}
function updateSettings(){const signature=JSON.stringify(state.settings);if(signature!==settingsUiSignature){settingsUiSignature=signature;document.querySelectorAll('[data-card-setting]').forEach(b=>{const checked=state.settings[b.dataset.cardSetting]===b.dataset.value;b.setAttribute('aria-checked',String(checked));b.tabIndex=checked?0:-1;});document.querySelectorAll('[data-setting]').forEach(control=>{const key=control.dataset.setting,value=state.settings[key];if(control.type==='checkbox')control.checked=value;else if(document.activeElement!==control)control.value=String(value);if(key==='GlassTransparency')control.disabled=!state.settings.Glass;});document.querySelectorAll('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.theme==='true')===state.settings.DarkMode)));if($('transparency-output'))$('transparency-output').value=`${document.activeElement===$('glass-transparency')?$('glass-transparency').value:state.settings.GlassTransparency} %`;if($('download-path'))$('download-path').textContent=state.settings.DownloadFolder;}if($('dns-feedback'))$('dns-feedback').textContent=trMessage(state.status)||(state.dnsRestartRequired?tr('Настройки сохранены. Перезапустите браузер.'):'');}
window.renderState=next=>{const languageChanged=state?.settings.Language!==next.settings.Language;setLanguage(next.settings.Language);if(languageChanged){renderedView=undefined;tabSignature='';tabStructureSignature='';listSignature='';settingsUiSignature='';popupSignature='';storeSignature='';localizeStatic();$('popup-menu').replaceChildren();document.querySelectorAll('dialog').forEach(d=>d.remove());}const resizing=document.documentElement.classList.contains('sidebar-resizing'),liveWidth=state?.pageLeft;state=next;if(resizing&&liveWidth!==undefined)state.pageLeft=liveWidth;theme(state.settings);window.setWindowState(state.edgeToEdge);if(popup){renderMenu();return;}const active=state.tabs.find(t=>t.id===state.active);$('sidebar-toggle').setAttribute('aria-pressed',String(state.settings.SidebarVisible));$('menu-toggle').setAttribute('aria-pressed',String(state.menuOpen&&state.popupMode==='menu'));$('page-actions').setAttribute('aria-pressed',String(state.menuOpen&&state.popupMode==='page'));$('translate-toggle').setAttribute('aria-pressed',String(state.menuOpen&&state.popupMode==='translate'));$('back').disabled=!state.canBack;$('forward').disabled=!state.canForward;$('reload').replaceChildren(icon(active?.loading?'stop':'reload'));$('reload').setAttribute('aria-label',active?.loading?tr('Остановить загрузку'):tr('Обновить страницу'));$('status').textContent=trMessage(state.status)||(state.private?tr('Приватное окно'):'');const activeDownloads=state.transfers.filter(d=>d.state==='progress').length;$('download-count').textContent=activeDownloads||'';$('sidebar-downloads').classList.toggle('has-downloads',activeDownloads>0);$('sidebar-downloads').setAttribute('aria-label',activeDownloads?tr`Загрузки: ${activeDownloads} активных`:tr('Загрузки'));$('sidebar').hidden=!!state.view||!state.settings.SidebarVisible;document.documentElement.dataset.layout=state.settings.BrowserLayout;document.documentElement.classList.toggle('settings-open',!!state.view);document.documentElement.classList.toggle('sidebar-hidden',!state.settings.SidebarVisible);$('sidebar-resizer').hidden=!!state.view||!state.settings.SidebarVisible;applySidebarWidth(state.pageLeft);$('workspace').style.top=state.view?'94px':`${state.pageTop}px`;const engineName=state.searchEngines.find(([id])=>id===state.settings.SearchEngine)?.[1]||'Google';$('address').placeholder=tr`Адрес сайта или поиск ${engineName}`;$('address').setAttribute('aria-label',tr`Адрес сайта или поиск ${engineName}`);$('home-input').placeholder=tr`Поиск ${engineName} или адрес сайта`;$('home-input').setAttribute('aria-label',tr`Поиск ${engineName} или адрес сайта`);$('home').hidden=!!state.view||!active||active.url!=='slim://newtab';$('view').hidden=!state.view;if(document.activeElement!==$('address'))$('address').value=active?.url&&active.url!=='slim://newtab'?displayAddress(active.url):'';renderTabs();if(renderedView!==state.view){renderedView=state.view;$('view').replaceChildren();listSignature='';settingsUiSignature='';if(state.view){if(['history','bookmarks'].includes(state.view))library($('view'),state.view);else if(state.view==='extension-store')extensionStore($('view'));else settings($('view'),state.view);}}updateSettings();updatePrivacyControls();updateLists();updateExtensionStore();updateSiteData();document.body.setAttribute('aria-busy',String(state.busy));};
function displayAddress(url){try{return new URL(url).host}catch{return url;}}
window.focusAddress=()=>{if(document.documentElement.classList.contains('sidebar-resizing'))return;$('address').focus();const active=state?.tabs.find(t=>t.id===state.active);$('address').value=active?.url&&active.url!=='slim://newtab'?active.url:'';$('address').select();};
$('address').addEventListener('focus',()=>{const active=state?.tabs.find(t=>t.id===state.active);$('address').value=active?.url&&active.url!=='slim://newtab'?active.url:'';});$('address').addEventListener('blur',()=>{const active=state?.tabs.find(t=>t.id===state.active);$('address').value=active?.url&&active.url!=='slim://newtab'?displayAddress(active.url):'';});
$('address-form').addEventListener('submit',e=>{e.preventDefault();post('navigate',{value:$('address').value});$('address').blur();});$('home-form').addEventListener('submit',e=>{e.preventDefault();post('navigate',{value:$('home-input').value});$('home-input').value='';});
$('drag-region').addEventListener('pointerdown',e=>{if(e.button===0&&e.detail<2)post('drag');});$('drag-region').addEventListener('dblclick',()=>post('maximize'));
document.addEventListener('dragend',endSidebarDrag);
document.addEventListener('keydown',e=>{let cmd;if(e.ctrlKey&&!e.altKey){cmd=({l:'focus_address',t:'new_tab',w:'close_tab',n:e.shiftKey?'private_window':'new_window',p:e.shiftKey?'private_window':undefined})[e.key.toLowerCase()];}if(e.key==='F5')cmd='reload';if(e.key==='F11')cmd='fullscreen';if(e.altKey&&e.key==='ArrowLeft')cmd='back';if(e.altKey&&e.key==='ArrowRight')cmd='forward';if(e.key==='Escape'&&document.querySelector('dialog[open]'))return;if(e.key==='Escape')cmd=popup?'close_menu':'escape';if(cmd){e.preventDefault();post(cmd);}});
if(!popup){setupSidebarResize();for(const edge of ['n','s','e','w','ne','nw','se','sw']){const div=el('div');div.dataset.edge=edge;div.addEventListener('pointerdown',e=>{if(e.button===0)post('resize',{value:edge});});$('resize-edges').append(div);}document.addEventListener('pointerdown',e=>{if(state?.menuOpen&&!e.target.closest('#menu-toggle,#page-actions,#translate-toggle,#sidebar-add,#sidebar-downloads'))post('close_menu');});}
