document.addEventListener('keydown',e=>{if(!popup||!['ArrowDown','ArrowUp','Home','End'].includes(e.key)||document.activeElement.matches('input,select'))return;const items=[...$('popup-menu').querySelectorAll('button:not(:disabled)')].filter(b=>b.getClientRects().length);if(!items.length)return;e.preventDefault();const i=items.indexOf(document.activeElement),n=e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[n].focus();});
